'use strict';
function settings(){const b=state.business;return head('Make this workspace yours.','Business identity and quotation preferences, kept together.')+`<div class="tabs"><a class="active" href="#/settings">Business profile</a><a href="#/settings-access">Access & integrations</a></div><form id="settings-form"><div class="grid"><section class="panel form-section"><h2>Business details</h2>${field('Business name','name',b.name)}<div class="form-grid">${field('Email address','email',b.email,'email')}${field('Phone number','phone',b.phone)}</div>${field('Business address','address',b.address)}<h2 style="margin-top:30px">Quotation preferences</h2><div class="form-grid">${field('Currency','currency','USD')}${field('Number prefix','prefix','BW-2026-')}</div>${field('Default terms','terms',b.terms||'Quotation valid for 30 days. Work starts after written confirmation.','textarea')}<button class="btn primary" type="submit">${I('check')}Save changes</button></section><aside class="aside-info"><h3>One consistent identity</h3><p>Your business details appear on quotation previews and printed documents.</p><p>Approval remains a provider action. Email requires a separate recipient confirmation.</p></aside></div></form>`}
function integrations(){return head('Access & integrations','Choose how your team and connected services support the workflow.')+`<div class="tabs"><a href="#/settings">Business profile</a><a class="active" href="#/settings-access">Access & integrations</a></div>`+panel('Workspace owner','Business access',`<div class="info-row"><span>Tawanda Mavambo</span><b>Owner · Quotation approver</b></div><p class="muted" style="font-size:12px;margin-top:18px">Additional approval roles can be configured when the access model is agreed.</p>`)+`<div class="cards">${[['spark','AI assistance','Catalogue matching and scope drafting. Manual preparation is always available.'],['mail','Email delivery','Explicit sending after provider approval, with a recorded delivery outcome.'],['file','Document output','Use the quotation preview and browser print dialog to print or save a PDF.']].map(([i,t,d])=>`<section class="service-card"><span class="square green">${I(i)}</span><h2>${t}</h2><p>${d}</p>${badge(i==='file'?'Available':'Not connected')}</section>`).join('')}</div>`}
const screens=[['dashboard','Overview','Workspace summary, recent requests and next actions.'],['requests','Requests','All requests, status filters and search.'],['new-request','New request','Customer, location and the customer’s own description.'],['request/1042','Request details','Original request, customer context and next step.'],['clarify/1042','Clarification','Catalogue questions, recorded answers and unknowns.'],['scope/1042','Scope review','Services, stages, exclusions and provider review.'],['catalogue','Service catalogue','Service categories and active offerings.'],['service/ELE-001','Service editor','Defaults, dependencies, questions and assessment needs.'],['service-new','New service','Create a reusable service definition.'],['customers','Customers','Contact records and linked work.'],['customer/1','Customer profile','Contact details and request history.'],['customer-new','New customer','Capture customer identity and contacts.'],['quotations','Quotations','Draft and approved quotations with revisions.'],['quote/128','Quotation details','Summary, source request and delivery record.'],['quote-edit/1042','Quotation editor','Provider-entered amounts, conditions and terms.'],['quote-preview/1042','Document preview','Approval, print, PDF and optional email design.'],['history/1042','Revision history','Retained approvals and revision information.'],['settings','Business settings','Provider identity and quotation defaults.'],['settings-access','Access & integrations','Approver identity and connection states.'],['sign-in','Sign in','Account access screen.']];
function brand(){return head('A brand built on clarity.','A distinctive identity and a complete set of connected screen designs.',`<a class="btn primary" href="/brand/buildwise-logo.svg" download>${I('download')}Download logo</a>`)+`<div class="grid"><div>${panel('The BuildWise identity','A strong B, joined by a clear mark of approval.',`<div class="brand-board"><img src="/brand/buildwise-logo.svg" alt="BuildWise logo"></div><p style="font-size:12px;color:var(--muted)">The geometric B represents structured building blocks. The lime check represents provider review and a scope you can stand behind.</p><div class="actions"><a class="btn small" href="/brand/buildwise-mark.svg" download>${I('download')}Download icon</a></div>`)}${panel('Colour & typography','Quiet confidence. Clear information.',`<div class="swatches"><div class="swatch" style="background:#173f35;color:#fff">Forest · #173F35</div><div class="swatch" style="background:#d2e6a2">Lime · #D2E6A2</div><div class="swatch" style="background:#f8f9f5;border:1px solid var(--line)">Ivory · #F8F9F5</div><div class="swatch" style="background:#fbf2de">Amber · #FBF2DE</div></div><h2 style="margin-top:25px">Manrope for headings</h2><p style="font-size:13px;color:var(--muted)">DM Sans for interface text. Segoe UI provides the local fallback.</p>`)}</div><aside class="aside-info"><h3>Designed for the first useful release</h3><p>A provider-led workspace for catalogue management, customer requests and approved quotations.</p><p>Customer portals, payments, scheduling and execution tracking remain later additions.</p></aside></div>`+panel('Explore every main screen',`${screens.length} connected screens · Desktop and mobile layouts`,`<div class="cards">${screens.map(([r,t,d],i)=>`<a class="service-card" href="#/${r}"><div class="eyebrow">${String(i+1).padStart(2,'0')}</div><h3>${t}</h3><p>${d}</p><span class="text-link">Open screen ${I('arrow')}</span></a>`).join('')}</div>`)}
function guide(){return head('From a request to a clear commitment.','A provider-led workflow, with room for professional judgement.',B('Start a request','new-request'))+panel('The BuildWise workflow','',`<div class="timeline">${[['Capture','Record the customer, work location and the requested work.'],['Clarify','Use service questions and keep unanswered details visible.'],['Review scope','Select offered services, confirm conditions and review exclusions.'],['Prepare quotation','Enter approved amounts, validity and commercial terms.'],['Approve & share','Approve the final document, then print, save as PDF or choose email.']].map(([t,d])=>`<div class="timeline-item"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`)}
function signIn(){return `<div class="auth"><div class="auth-art"><a class="brand" href="#/dashboard"><img src="/brand/buildwise-mark.svg" alt="">BuildWise.</a><div style="position:relative;z-index:1"><div class="eyebrow" style="color:#c9dfaa">FROM REQUEST TO QUOTATION</div><h1>Your expertise.<br>A clearer way<br>to bring it together.</h1><p>Plan the work, define the scope and prepare quotations with confidence.</p></div><small style="color:#b4c6ad">© 2026 BuildWise</small></div><form class="auth-form" id="signin-form"><div class="eyebrow">WELCOME BACK</div><h1>A good place to get to work.</h1><p style="margin-bottom:32px">Sign in to your BuildWise workspace.</p>${field('Email address','email','tawanda@mavambo.example','email')}${field('Password','password','','password')}<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><label class="check"><input type="checkbox">Remember me</label><button type="button" class="icon-btn" data-action="forgot" style="font-size:11px">Forgot password?</button></div><button class="btn primary" type="submit">Sign in ${I('arrow')}</button><p style="text-align:center;margin-top:25px">First time here? <a class="text-link" href="#/settings">Set up your business</a></p></form></div>`}
function catalogue(){let rows=state.services.filter(s=>category==='All services'||s.category===category);return head('Your expertise, organised.','Define what you offer. Build every scope on a clear foundation.',B('Add service','service-new'))+`<div class="tabs">${['All services','Electrical','Painting','Plumbing','Renovations','Maintenance'].map(t=>`<a href="#/catalogue" data-category="${t}" class="${category===t?'active':''}">${t}</a>`).join('')}</div><div class="cards">${rows.map(s=>`<a class="service-card" href="#/service/${s.id}"><div style="display:flex;justify-content:space-between"><span class="square ${s.category==='Electrical'?'':'green'}">${I(s.icon)}</span>${badge(s.active?'Active':'Inactive')}</div><div class="eyebrow">${esc(s.id)} · ${esc(s.category)}</div><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><div class="card-foot"><span>${s.questions} clarification questions</span><span>${s.assessment?'Assessment required':I('arrow')}</span></div></a>`).join('')}</div>`}
function service(isNew=false){const id=location.hash.split('/')[2],s=state.services.find(s=>s.id===id)||state.services[0];return head(isNew?'Define a new service.':s.name,'Reusable scope, clear questions and sensible boundaries.',B('Back to catalogue','catalogue','arrow',''),isNew?'Service catalogue':s.id)+`<form id="service-form" data-id="${isNew?'':s.id}"><div class="grid"><section class="panel form-section"><h2>Service details</h2>${field('Service name','name',isNew?'':s.name)}<div class="form-grid">${field('Category','category',isNew?'':s.category)}${field('Applicable unit','unit',s.unit||'Per assessment / agreed scope')}</div>${field('Description','description',isNew?'':s.description,'textarea')}${field('Inclusions','inclusions',s.inclusions||'Agreed work, standard preparation and inspection.','textarea')}${field('Exclusions','exclusions',s.exclusions||'Unrelated work, concealed defects and additional finishes.','textarea')}${field('Normal work stages and dependencies','stages',s.stages||'Assessment → confirm scope → service work → inspection.','textarea')}${field('Required customer information','questions',s.questionText||getQuestions({category:s.category}).join('\n'),'textarea','One question per line. Questions can be adapted for each request.')}<label class="check"><input name="assessment" type="checkbox" ${!isNew&&s.assessment?'checked':''}>A site assessment is required.</label><label class="check"><input name="active" type="checkbox" ${isNew||s.active?'checked':''}>Active and available for new scopes.</label><button class="btn primary" type="submit">${I('check')}Save service</button></section><aside class="aside-info"><h3>A catalogue you can stand behind</h3><p>Describe work your business actually offers. These details provide the starting point for request questions and scope drafting.</p><p>Previously issued quotations keep their own approved descriptions when a service changes.</p></aside></div></form>`}
function customerRows(rows){return rows.map(c=>`<tr class="record" data-href="customer/${c.id}"><td><a href="#/customer/${c.id}"><strong>${esc(c.name)}</strong><small>CUS-${String(c.id).padStart(4,'0')}</small></a></td><td>${esc(c.email)}<small>${esc(c.phone)}</small></td><td>${esc(c.location)}</td><td>${state.requests.filter(r=>r.customer===c.id).length}</td><td>${I('chevron')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching customers.</td></tr>'}
function customers(){return head('Good work starts with people.','Customer details, requests and quotations in one place.',B('Add customer','customer-new'))+`<section class="panel"><div class="toolbar"><label class="field-search">${I('search')}<input id="customer-search" placeholder="Find a customer" aria-label="Find a customer"></label><span class="badge">${state.customers.length} customers</span></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Location</th><th>Requests</th><th></th></tr></thead><tbody id="customer-results">${customerRows(state.customers)}</tbody></table></div></section>`}
function customerPage(isNew=false){const c=customer(location.hash.split('/')[2]);return head(isNew?'Meet your next customer.':c.name,isNew?'Keep the essentials handy for every conversation.':`CUS-${String(c.id).padStart(4,'0')} · Customer profile`,B('All customers','customers','users',''))+`<div class="grid"><div><form id="customer-form" data-id="${isNew?'':c.id}" class="panel form-section"><h2>Contact details</h2>${field('Customer or business name','name',isNew?'':c.name)}<div class="form-grid">${field('Email address','email',isNew?'':c.email,'email')}${field('Phone number','phone',isNew?'':c.phone)}</div>${field('Site / location','location',isNew?'':c.location)}<button class="btn primary" type="submit">${I('check')}Save customer</button></form>${isNew?'':`<section class="panel"><div class="panel-head"><h2>Customer requests</h2>${B('New request','new-request','plus','small')}</div>${requestTable(state.requests.filter(r=>r.customer===c.id),true)}</section>`}</div><aside class="aside-info">${I('users')}<h3 style="margin-top:16px">One customer, many possibilities</h3><p>Keep a customer’s requests together, whether they need one repair or several services across a property.</p><p>Email is optional when sharing a quotation. You can always print a copy.</p></aside></div>`}
function getDraft(r=currentRequest()){if(!state.drafts[r.id]){const q=state.quotes.find(q=>q.request===r.id),base=q?q.total:720;state.drafts[r.id]={number:q?q.id:129+Object.keys(state.drafts).length,rates:[base*.15,base*.5,base*.2,base*.15],terms:'Quotation valid for 30 days. Work starts after written confirmation. Changes to the agreed scope will be quoted separately.',exclusions:r.category==='Electrical'?'External supply connection, concealed defects and making good wall finishes are excluded unless agreed separately.':'Unrelated work, concealed defects and any additional services are excluded unless agreed separately.',approved:q?.status==='Approved',revision:q?.revision||1,history:[],deliveries:[]}}return state.drafts[r.id]}
const draftTotal=d=>d.rates.reduce((a,b)=>a+Number(b),0);
const quoteNumber=d=>`BW-2026-${String(d.number).padStart(4,'0')}`;
function quotations(){return head('Clear work. Clear quotations.','Prepare, review and share a record of exactly what’s included.',B('Create quotation','quote-edit/1042'))+`<div class="tabs">${['All quotations','Draft','Approved'].map(t=>`<a href="#/quotations" data-quote-filter="${t}" class="${quoteFilter===t?'active':''}">${t}</a>`).join('')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Quotation</th><th>Customer / work</th><th>Revision</th><th>Status</th><th>Amount</th><th></th></tr></thead><tbody>${state.quotes.filter(q=>quoteFilter==='All quotations'||q.status===quoteFilter).map(q=>{let r=state.requests.find(r=>r.id===q.request);return `<tr class="record" data-href="quote/${q.id}"><td><a href="#/quote/${q.id}"><strong>BW-2026-${String(q.id).padStart(4,'0')}</strong><small>01 Nov 2026</small></a></td><td>${esc(customer(r.customer).name)}<small>${esc(r.title)}</small></td><td>Revision ${q.revision}</td><td>${badge(q.status)}</td><td>${money(q.total)}</td><td>${I('chevron')}</td></tr>`}).join('')}</tbody></table></div></section><div class="aside-info"><h3>Approval and delivery are recorded separately.</h3><p style="margin-bottom:0">Approval confirms the provider has reviewed the quotation. Download, print and email events show how a particular revision was shared.</p></div>`}
function quoteDetail(){const q=state.quotes.find(q=>q.id===Number(location.hash.split('/')[2]))||state.quotes[0],r=state.requests.find(r=>r.id===q.request);return head(`BW-2026-${String(q.id).padStart(4,'0')}`,`${customer(r.customer).name} · ${r.title}`,B('Preview quotation',`quote-preview/${r.id}`,'file'),`Revision ${q.revision}`)+`<div class="grid"><div>${panel('Quotation overview','',`<div class="actions" style="margin:12px 0 20px">${badge(q.status)}<span class="badge">Revision ${q.revision}</span></div><div class="summary-number">${money(q.total)}</div><p class="muted" style="font-size:12px">Provider-entered amount · USD</p><div class="info-row"><span>Customer</span><b>${esc(customer(r.customer).name)}</b></div><div class="info-row"><span>Location</span><b>${esc(customer(r.customer).location)}</b></div><div class="info-row"><span>Source request</span><a href="#/request/${r.id}">REQ-${r.id}</a></div><div class="info-row"><span>Validity</span><b>30 days from issue</b></div><div class="actions" style="margin-top:24px">${B(q.status==='Approved'?'Create revision':'Edit quotation',`quote-edit/${r.id}`,'edit','')}${B('Revision history',`history/${r.id}`,'history','')}</div>`)}${panel('Delivery record','Each event belongs to a specific revision.',`<div class="timeline"><div class="timeline-item"><h3>${q.status==='Approved'?'Quotation approved':'Quotation in preparation'}</h3><p>Tawanda Mavambo · Revision ${q.revision}</p></div><div class="timeline-item"><h3>No email delivery recorded</h3><p>Confirm the recipient before sending the approved revision.</p></div></div>`)}</div><div class="aside-info"><h3>Ready when you are</h3><p>Review the saved document before sharing. Email is an optional step after approval.</p>${B('Open document',`quote-preview/${r.id}`,'arrow','small')}</div></div>`}
function quoteEdit(){const r=currentRequest(),d=getDraft(r),items=getScope(r);return head('Put the details on paper.',`REQ-${r.id} · ${customer(r.customer).name}`,B('Preview quotation',`quote-preview/${r.id}`,'file'))+steps(3)+`<form id="quote-form"><div class="quote-layout"><div><section class="panel"><div class="panel-head"><div><h2>Quotation items</h2><p>Enter your own amounts. Unknown quantities stay visible.</p></div>${badge(d.approved?'New revision':'Draft')}</div><div class="table-wrap"><table><thead><tr><th>Service / stage</th><th>Quantity</th><th>Amount (USD)</th></tr></thead><tbody>${items.map((s,i)=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.service)}</small></td><td>${i===0?'1 visit':'Subject to assessment'}</td><td><input class="amount" aria-label="Amount for ${esc(s.name)}" name="rate${i}" type="number" min="0" step="0.01" value="${(d.rates[i]||0).toFixed(2)}"></td></tr>`).join('')}</tbody></table></div><div class="form-section">${field('Exclusions & unresolved conditions','exclusions',d.exclusions,'textarea')}${field('Terms & validity','terms',d.terms,'textarea')}<div class="callout">${I('alert')}Amounts are provider-entered allowances. Final quantities and any changes require confirmation after assessment.</div><button class="btn primary" type="submit">${I('check')}Save quotation</button></div></section></div><div>${panel('Quotation summary','All amounts in USD.',`<div class="info-row"><span>Services</span><b>${items.length} stages</b></div><div class="info-row"><span>Subtotal</span><b id="quote-subtotal">${money(draftTotal(d))}</b></div><div class="info-row"><span>Tax</span><b>Not applied</b></div><div class="info-row"><span>Total</span><b id="quote-total">${money(draftTotal(d))}</b></div><p class="muted" style="font-size:10px;margin-top:18px">Tax treatment and commercial rules can be configured when agreed.</p>`)}<div class="aside-info"><h3>Your approval comes next.</h3><p>Check scope, conditions and amounts in the preview. The quotation remains editable until approved.</p></div></div></div></form>`}
function quotePreview(){const r=currentRequest(),c=customer(r.customer),d=getDraft(r),items=d.approved&&d.snapshot?d.snapshot.items:getScope(r),provider=d.approved&&d.snapshot?d.snapshot.business:state.business,contact=d.approved&&d.snapshot?d.snapshot.customer:c;return head('One last look before you share.',`${c.name} · Revision ${d.revision}`,`${action('Print / Save PDF','print','print')}${action('Email','email','mail')}${d.approved?B('Create revision',`quote-edit/${r.id}`,'edit',''):action('Approve quotation','approve','check','primary')}`)+`<div class="document" id="quotation-document"><div class="doc-head"><div><img src="/brand/buildwise-logo.svg" alt="BuildWise"><p style="margin:15px 0 0"><b>${esc(provider.name)}</b><br>${esc(provider.address)}<br>${esc(provider.email)} · ${esc(provider.phone)}</p></div><div><div class="eyebrow">SERVICE QUOTATION</div><h1>${quoteNumber(d)}</h1><p>Revision ${d.revision} · ${d.approved?'Approved':'Draft'}<br>Prepared: 1 November 2026<br>Valid for 30 days</p></div></div><div class="form-grid"><div><div class="eyebrow">PREPARED FOR</div><h3>${esc(contact.name)}</h3><p>${esc(contact.email)}<br>${esc(contact.phone)}</p></div><div><div class="eyebrow">WORK LOCATION</div><h3>${esc(r.location||contact.location)}</h3><p>${esc(r.title)}<br>Request REQ-${r.id}</p></div></div><h2>Scope of work</h2><p>Services for the agreed areas of the existing property. Installation conditions and quantities are subject to site assessment and provider confirmation.</p><table><thead><tr><th>Service</th><th>Quantity / condition</th><th style="text-align:right">Amount (USD)</th></tr></thead><tbody>${items.map((s,i)=>`<tr><td><b>${esc(s.name)}</b><br>${esc(s.notes)}</td><td>${i===0?'1 assessment':'To be confirmed on site'}</td><td style="text-align:right">${money(d.rates[i])}</td></tr>`).join('')}</tbody></table><div class="totals"><div class="info-row"><span>Subtotal</span><b>${money(draftTotal(d))}</b></div><div class="info-row"><span>Tax</span><b>Not applied</b></div><div class="info-row"><span>Total USD</span><b>${money(draftTotal(d))}</b></div></div><h2>Exclusions & unresolved conditions</h2><p>${esc(d.exclusions)}</p><p>Existing conditions, final quantities and applicable technical requirements require provider confirmation.</p><h2>Terms & validity</h2><p>${esc(d.terms)}</p><div style="border-top:1px solid var(--line);padding-top:20px;margin-top:30px"><p style="margin:0">Prepared by Tawanda Mavambo · ${esc(provider.name)}<br>${d.approved?'Approved for issue by the provider.':'Awaiting provider approval. This draft has not been approved for issue.'}</p></div></div>`}
function history(){const d=getDraft();return head('A clear record of every change.','Issued revisions retain the wording and amounts approved at that time.',B('Back to quotation',`quote-preview/${currentRequest().id}`,'arrow',''))+panel('Revision history',quoteNumber(d),`<div class="timeline"><div class="timeline-item"><div class="scope-top"><h3>Revision ${d.revision} · Current</h3>${badge(d.approved?'Approved':'Draft')}</div><p>1 November 2026 · Tawanda Mavambo · ${money(draftTotal(d))}</p></div>${d.history.map((h,i)=>`<div class="timeline-item"><h3>Revision ${h.revision} · Approved</h3><p>Retained document snapshot · ${money(h.rates.reduce((a,b)=>a+b,0))}</p>${action('View retained revision',`view-revision-${i}`,'file','small')}</div>`).join('')}<div class="timeline-item"><h3>Request captured</h3><p>The customer description and clarification answers form the source of the scope.</p></div></div><div class="callout">${I('history')}When requirements change after approval, save a new revision and keep the earlier approved document.</div>`)}
function dashboard(){return head('A little clarity goes a long way.','Here’s what’s happening in your workspace today.',B('New request','new-request'),'Sunday, 1 November 2026')+`<div class="banner"><div class="banner-symbol">${I('spark')}</div><div><h2>From a conversation to a confident quotation.</h2><p>Capture a request. Shape the scope. Let your expertise do the rest.</p></div>${B('Create a request','new-request','arrow','')}</div><div class="stats">${[['Open requests',String(state.requests.length),'file','2 need your attention'],['Draft quotations',String(state.quotes.filter(q=>q.status==='Draft').length),'edit','Ready for your next review'],['Approved quotations',String(state.quotes.filter(q=>q.status==='Approved').length),'check','Provider reviewed and approved'],['Active services',String(state.services.filter(s=>s.active).length),'box','Across 5 service categories']].map(([t,v,i,s])=>`<div class="stat"><div class="stat-top">${t}<span class="stat-icon">${I(i)}</span></div><div class="stat-value">${v}</div><div class="stat-bottom">${s}</div></div>`).join('')}</div><div class="grid"><div><section class="panel"><div class="panel-head"><div><h2>Recent requests</h2><p>Your latest conversations, taking shape.</p></div><a class="text-link" href="#/requests">View all ${I('arrow')}</a></div>${requestTable(state.requests.slice(0,4),true)}<div class="table-foot"><span>${state.requests.length} requests in your workspace</span><span>Updated today</span></div></section>${panel('Quotation activity','A look at your last six months.',`<div class="chart">${['Jun','Jul','Aug','Sep','Oct','Nov'].map((m,i)=>`<div class="bar-group"><div class="bar" style="height:${[30,48,41,68,86,58][i]}%"></div><div class="bar dark" style="height:${[20,30,32,46,65,38][i]}%"></div><span>${m}</span></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>Prepared</span><span><i class="dot dark"></i>Approved</span></div>`,`<span class="badge">Jun – Nov 2026</span>`)}</div><div>${panel('Needs your attention','A few things to keep moving.',`<div class="attention-item"><span class="square">${I('alert')}</span><div><h3>Electrical installation</h3><p>Tendai Moyo · 3 details still need confirming.</p><a href="#/clarify/1042">Review questions →</a></div></div><div class="attention-item"><span class="square green">${I('check')}</span><div><h3>A scope is ready for review</h3><p>Sarah Chikore · Interior painting.</p><a href="#/scope/1041">Review scope →</a></div></div><div class="attention-item"><span class="square blue">${I('file')}</span><div><h3>Finish your draft quotation</h3><p>David Nyathi · Kitchen renovation.</p><a href="#/quote/127">Open quotation →</a></div></div>`)}${panel('Recent activity','The latest in your workspace.',`<div class="activity"><span class="avatar">TM</span><div><p>You created a new request for <b>Tendai Moyo</b>.</p><small>Today, 10:42</small></div></div><div class="activity"><span class="avatar">✓</span><div><p>Quotation <b>BW-2026-0128</b> was approved.</p><small>Yesterday, 15:18</small></div></div><div class="activity"><span class="avatar">MP</span><div><p>You updated <b>Electrical installation</b> in your catalogue.</p><small>30 October, 09:30</small></div></div>`)}</div></div>`}
function requests(){return head('Every request starts here.','Capture the conversation and keep the next step in sight.',B('New request','new-request'))+`<div class="tabs">${['All requests','Needs clarification','Scope review','Ready to quote'].map(t=>`<a href="#/requests" data-filter="${t}" class="${requestFilter===t?'active':''}">${t}${t==='All requests'?` (${state.requests.length})`:''}</a>`).join('')}</div><section class="panel"><div class="toolbar"><label class="field-search">${I('search')}<input id="list-search" placeholder="Search by request or customer" aria-label="Search requests"></label><span class="badge">${state.requests.length} requests</span></div><div id="request-results">${requestTable(state.requests.filter(r=>requestFilter==='All requests'||r.status===requestFilter))}</div></section>`}
function requestDetail(){const r=currentRequest(),c=customer(r.customer);return head(r.title,`REQ-${r.id} · Created ${r.date}`,B('Continue request',`clarify/${r.id}`,'arrow'),c.name)+steps(0)+`<div class="grid"><div>${panel('The customer’s request','Recorded in their own words.',`<p style="font-size:16px;line-height:1.9">“${esc(r.description)}”</p><div class="actions">${badge(r.status)}<span class="badge">${esc(r.category)}</span></div>`)}${panel('Request details','Keep the known facts together.',`<div class="info-row"><span>Customer</span><a href="#/customer/${c.id}">${esc(c.name)}</a></div><div class="info-row"><span>Work location</span><b>${esc(r.location||c.location)}</b></div><div class="info-row"><span>Property</span><b>${esc(r.property||'Existing property')}</b></div><div class="info-row"><span>Attachments</span><b>No files attached</b></div>`)}</div><div>${panel('Customer','',`<div style="display:flex;gap:12px;align-items:center;margin:12px 0 20px"><span class="avatar">${esc(c.name.split(' ').map(n=>n[0]).join('').slice(0,2))}</span><div><h3>${esc(c.name)}</h3><small>${esc(c.location)}</small></div></div><p style="font-size:12px">${esc(c.email)}<br>${esc(c.phone)}</p>${B('View customer',`customer/${c.id}`,'users','small')}`)}<div class="aside-info">${I('spark')}<h3 style="margin-top:15px">A helpful starting point</h3><p>Use the catalogue questions to clarify this request. Unknown details stay visible until you confirm them.</p>${B('Select services manually',`scope/${r.id}`,'box','small')}</div></div></div>`}
function newRequest(){return head('Let’s understand the work.','Start with the customer and what they need. The details come next.',B('Back to requests','requests','arrow',''))+steps(0)+`<form id="request-form"><div class="grid"><section class="panel form-section"><h2>Customer & location</h2><div class="field"><label for="customer">Customer</label><select id="customer" name="customer">${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.email)}</option>`).join('')}</select><a class="text-link" href="#/customer-new">+ Add a new customer</a></div>${field('Work location','location','Borrowdale, Harare')}<h2 style="margin-top:30px">What work is needed?</h2>${field('Request title','title','','text','Give the request a short, recognisable name.')}${field('Customer description','description','','textarea','Capture the customer’s own words, including anything they are unsure about.')}<div class="form-grid"><div class="field"><label for="category">Service category</label><select name="category" id="category">${['Electrical','Painting','Plumbing','Renovations','Maintenance','Not sure yet'].map(c=>`<option>${c}</option>`).join('')}</select></div>${field('Property type','property','Existing residential property')}</div><div class="actions"><button class="btn primary" type="submit">Save & clarify ${I('arrow')}</button></div></section><aside class="aside-info">${I('file')}<h3 style="margin-top:16px">Start simple. Add clarity.</h3><p>A request can be a single repair, work on an existing property, or a complete project.</p><ul><li>Record the work location.</li><li>Keep the customer’s meaning intact.</li><li>Leave unknown quantities open.</li></ul><p>You can choose services and prepare a scope manually at any time.</p></aside></div></form>`}
function getQuestions(r){if(r.category==='Electrical')return ['Which areas need work?','Does wiring already exist?','Which fittings are required?','Are electrical drawings available?','Is external supply connection required?'];if(r.category==='Painting')return ['Which rooms or surfaces need painting?','What is the condition of the surfaces?','Which finishes and colours are required?','Are access arrangements confirmed?'];if(r.category==='Plumbing')return ['Which fixtures or areas are affected?','What leaks or faults have been observed?','Can the water supply be isolated?','Is a site inspection needed?'];return ['Which areas are affected?','What work is required?','What existing conditions are known?','Is a site assessment required?']}
function clarify(){const r=currentRequest(),qs=getQuestions(r);let vals=state.answers[r.id]||(r.id===1042?['Three bedrooms, kitchen and living room','Unknown','Socket outlets and light fittings','Unknown','Unknown']:qs.map(()=>'Unknown'));return head('A few details make all the difference.',`REQ-${r.id} · ${r.title}`,B('Review scope',`scope/${r.id}`,'arrow'))+steps(1)+`<div class="grid"><form id="clarify-form" class="panel form-section"><h2>Clarification questions</h2><p class="muted" style="font-size:12px">From your ${esc(r.category)} service catalogue</p><div class="callout">${I('alert')}Keep unanswered details as “Unknown”. They will remain visible in the scope and quotation.</div>${qs.map((q,i)=>field(q,`answer${i}`,vals[i]||'Unknown')).join('')}<div class="actions"><button class="btn primary" type="submit">Save answers ${I('check')}</button>${B('Continue to scope',`scope/${r.id}`,'arrow','')}</div></form><div>${panel('Original request','',`<p style="font-size:13px">“${esc(r.description)}”</p><div class="info-row"><span>Customer</span><b>${esc(customer(r.customer).name)}</b></div>`)}<div class="aside-info">${I('spark')}<h3 style="margin-top:16px">Catalogue-guided assistance</h3><p>Questions come from services your business offers. Suggested services and wording always need your review.</p>${action('Request AI suggestions','ai','spark','small')}<p style="font-size:10px;margin-bottom:0">Manual selection remains available.</p></div></div></div>`}
function getScope(r=currentRequest()){if(!state.scopes[r.id]){let service=state.services.find(s=>s.category===r.category);let names=r.category==='Electrical'?['Site assessment','Internal wiring','Sockets & light fittings','Inspection & testing']:r.category==='Painting'?['Surface assessment','Surface preparation','Painting & finishing','Final inspection']:r.category==='Plumbing'?['Site inspection','Fault repair','Fixture replacement','Testing & handover']:['Site assessment','Preparation','Agreed service work','Final inspection'];state.scopes[r.id]=names.map((n,i)=>({name:n,service:i===0&&r.category==='Electrical'?'ELE-002':service?.id||'Unmatched',notes:['Assess the affected areas and confirm existing conditions.','Prepare and carry out agreed work after confirming the scope.','Complete the agreed service. Quantities remain subject to assessment.','Inspect completed work and confirm applicable technical requirements.'][i]}))}return state.scopes[r.id]}
function scope(){const r=currentRequest(),items=getScope(r);return head('Shape the scope with confidence.',`REQ-${r.id} · ${r.title}`,B('Prepare quotation',`quote-edit/${r.id}`,'arrow'))+steps(2)+`<div class="grid"><div><div class="callout">${I('alert')}Unanswered details and final quantities require confirmation during the site assessment.</div>${panel('Proposed scope','Review each item before adding it to the quotation.',items.map((s,i)=>`<div class="scope-item"><div class="scope-top"><h3>${i+1}. ${esc(s.name)}</h3>${badge(i===0?'Site assessment':'Provider review')}</div><p>${esc(s.notes)}</p><div class="actions"><span class="badge">${esc(s.service)}</span><span class="badge">${i===0?'1 assessment':'Quantity: unknown'}</span>${action('Edit item',`edit-scope-${i}`,'edit','small')}</div></div>`).join(''),action('Add service','add-scope','plus','small'))}</div><div>${panel('Scope summary','',`<div class="info-row"><span>Work stages</span><b>${items.length}</b></div><div class="info-row"><span>Site assessment</span><b>Required</b></div><label class="check"><input type="checkbox" id="scope-approved" ${state.scopeApproved[r.id]?'checked':''}>I have reviewed the selected services, conditions and exclusions.</label>${action('Confirm scope','confirm-scope','check','primary')}`)}${panel('Exclusions & conditions','Keep responsibilities clear.',`<p style="font-size:12px;color:var(--muted)">${esc(getDraft(r).exclusions)}</p><p style="font-size:12px;color:var(--muted)">Quantities, existing conditions and applicable technical specifications must be confirmed at the site assessment.</p>`)}</div></div>`}
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 6"/>',box:'<path d="m3 7 9-5 9 5v10l-9 5-9-5V7zm0 0 9 5 9-5M12 12v10M7 5l10 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m7 10 5 5 5-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5l-2 4zm5 3h4"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="11" r="3"/>',spark:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3zM20 2v4M18 4h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2L12 3zm0 6v5m0 3v1"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',paint:'<path d="M4 3h14v7H4zM18 6h3v8H11v7H8v-7h3"/>',tool:'<path d="M21 3a6 6 0 0 1-8 8L5 21l-3-3 9-9a6 6 0 0 1 8-8l-4 4 4 2z"/>',home:'<path d="m2 11 10-9 10 9M5 9v13h14V9M10 22v-8h4v8"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',print:'<path d="M6 8V2h12v6M6 17H3V8h18v9h-3M6 14h12v8H6z"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2"/>',edit:'<path d="m15 3 6 6-12 12H3v-6L15 3zm-2 2 6 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',logout:'<path d="M9 3H3v18h6M9 12h12m-5-5 5 5-5 5"/>'};
const I=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={customers:[{id:1,name:'Tendai Moyo',email:'tendai.moyo@example.com',phone:'+263 77 234 5678',location:'Borrowdale, Harare'},{id:2,name:'Sarah Chikore',email:'sarah.chikore@example.com',phone:'+263 71 456 7890',location:'Mount Pleasant, Harare'},{id:3,name:'Westgate Properties',email:'projects@westgate.example',phone:'+263 24 223 4500',location:'Westgate, Harare'},{id:4,name:'David Nyathi',email:'david.nyathi@example.com',phone:'+263 78 345 6120',location:'Greendale, Harare'}],requests:[{id:1042,title:'Electrical installation',customer:1,category:'Electrical',status:'Needs clarification',date:'01 Nov 2026',description:'My house is already built. I need electrical installation in three bedrooms, a kitchen and a living room. I would like new sockets and light fittings.'},{id:1041,title:'Interior painting',customer:2,category:'Painting',status:'Scope review',date:'31 Oct 2026',description:'Repaint the interior walls of a three-bedroom home.'},{id:1040,title:'Office plumbing repairs',customer:3,category:'Plumbing',status:'Ready to quote',date:'30 Oct 2026',description:'Repair leaking taps and inspect the office bathroom plumbing.'},{id:1039,title:'Kitchen renovation',customer:4,category:'Renovations',status:'Draft quotation',date:'29 Oct 2026',description:'Upgrade existing kitchen cabinets and finishes.'}],services:[{id:'ELE-001',name:'Electrical installation',category:'Electrical',icon:'bolt',description:'Internal wiring, socket outlets and light fittings for new and existing properties.',questions:5,assessment:true,active:true},{id:'PNT-001',name:'Interior & exterior painting',category:'Painting',icon:'paint',description:'Surface preparation and professional paint finishes for walls, ceilings and exteriors.',questions:4,assessment:false,active:true},{id:'PLB-001',name:'Plumbing & repairs',category:'Plumbing',icon:'tool',description:'Water supply, drainage installation and repairs to existing plumbing systems.',questions:6,assessment:true,active:true},{id:'REN-001',name:'Property renovations',category:'Renovations',icon:'home',description:'Planned improvements to existing rooms, finishes and functional spaces.',questions:7,assessment:true,active:true},{id:'ELE-002',name:'Electrical site assessment',category:'Electrical',icon:'search',description:'Inspect existing wiring, confirm affected areas and document site conditions.',questions:3,assessment:true,active:true},{id:'MNT-001',name:'General maintenance',category:'Maintenance',icon:'tool',description:'Routine property care, minor repairs and preventative maintenance work.',questions:4,assessment:false,active:true}],quotes:[{id:128,request:1040,status:'Approved',total:480,revision:1},{id:127,request:1039,status:'Draft',total:2450,revision:2}],answers:{},scopes:{},drafts:{},scopeApproved:{},business:{name:'Mavambo Projects',email:'hello@mavambo.example',phone:'+263 77 123 4567',address:'24 Samora Machel Avenue, Harare',currency:'USD'}};
let state;try{state=JSON.parse(localStorage.getItem('buildwise-workspace-v2'))||structuredClone(initial)}catch{state=structuredClone(initial)}
let category='All services',requestFilter='All requests',quoteFilter='All quotations';
const save=()=>localStorage.setItem('buildwise-workspace-v2',JSON.stringify(state));
const customer=id=>state.customers.find(c=>c.id===Number(id))||state.customers[0];
const currentRequest=()=>state.requests.find(r=>r.id===Number(location.hash.split('/')[2]))||state.requests[0];
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v)||0);
const B=(text,route,icon='plus',kind='primary')=>`<a class="btn ${kind}" href="#/${route}">${I(icon)}${text}</a>`;
const action=(text,name,icon='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${name}">${icon?I(icon):''}${text}</button>`;
const badge=s=>`<span class="badge ${/clarification|Pending/.test(s)?'amber':/Approved|Active|Ready|Confirmed/.test(s)?'green':/Scope|review/.test(s)?'purple':/Draft/.test(s)?'':'blue'}">${esc(s)}</span>`;
const head=(title,sub,buttons='',eyebrow='')=>`<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${buttons}</div></div>`;
const panel=(title,sub,body,extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div><div class="panel-body">${body}</div></section>`;
const field=(label,name,value='',type='text',hint='')=>`<div class="field"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${['name','title','email'].includes(name)?'required':''}>`}${hint?`<small>${hint}</small>`:''}</div>`;
const steps=n=>`<div class="steps">${['Capture request','Clarify details','Review scope','Prepare quotation','Approve & share'].map((v,i)=>`<div class="step ${i<=n?'active':''}"><i>${i<n?'✓':i+1}</i>${v}</div>`).join('')}</div>`;
const requestTable=(rows,compact=false)=>`<div class="table-wrap"><table><thead><tr><th>Request / customer</th>${compact?'':'<th>Category</th>'}<th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr class="record" data-href="request/${r.id}"><td><a href="#/request/${r.id}"><strong>${esc(r.title)}</strong><small>${esc(customer(r.customer).name)} <span class="muted">· REQ-${r.id}</span></small></a></td>${compact?'':`<td>${esc(r.category)}</td>`}<td>${badge(r.status)}</td><td class="muted" style="font-size:10px;white-space:nowrap">${r.date}</td><td>${I('chevron')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No requests match your search.</td></tr>'}</tbody></table></div>`;
function shell(page,body){let section=['request','new-request','clarify','scope'].includes(page)?'requests':['quote','quote-edit','quote-preview','history'].includes(page)?'quotations':['service','service-new'].includes(page)?'catalogue':['customer','customer-new'].includes(page)?'customers':page;let nav=[['dashboard','grid','Overview'],['requests','file','Requests'],['quotations','file','Quotations'],['customers','users','Customers'],['catalogue','box','Service catalogue']];return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><img src="/brand/buildwise-mark.svg" alt="">BuildWise<span style="color:#a8bb8b;font-size:22px">.</span></a><a href="#/settings" class="workspace"><span class="avatar">MP</span><div><b>${esc(state.business.name)}</b><small>Business workspace</small></div><span style="margin-left:auto">${I('down')}</span></a><div class="nav-caption">WORKSPACE</div><nav class="nav">${nav.map(([r,i,t])=>`<a href="#/${r}" class="${section===r?'active':''}">${I(i)}${t}${r==='requests'?`<span class="count">${state.requests.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><a href="#/brand" class="${section==='brand'?'active':''}">${I('spark')}Brand & screen guide</a><a href="#/settings" class="${section==='settings'?'active':''}">${I('settings')}Settings</a></nav><div class="help"><h3 style="font-size:11px">A clearer scope. A better quote.</h3><p>Your services, your expertise.<br>BuildWise brings it together.</p><a href="#/guide">Explore the workflow ${I('arrow')}</a></div><div class="user"><span class="avatar">TM</span><div><b>Tawanda Mavambo</b><small>Business owner</small></div><a href="#/sign-in" style="margin-left:auto" aria-label="Sign in screen">${I('logout')}</a></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Toggle navigation">${I('menu')}</button>Workspace ${I('chevron')} <b>${({dashboard:'Overview',catalogue:'Service catalogue',requests:'Requests',quotations:'Quotations',customers:'Customers',settings:'Settings',brand:'Brand & screen guide',guide:'Workflow guide'})[section]||'Workspace'}</b></div><div class="top-actions"><form class="searchbox" id="global-search">${I('search')}<input name="q" placeholder="Search requests…" aria-label="Search requests"><span class="key">↵</span></form><button class="icon-btn notification" data-action="notifications" aria-label="Notifications">${I('bell')}</button><span class="avatar" style="width:30px;height:30px">TM</span></div></header><div class="content">${body}<footer class="footer-note"><span>© 2026 BuildWise. Built around your expertise.</span><span>Service planning, made clear.</span></footer></div></main></div>`}

function render(){const page=location.hash.split('/')[1]||'dashboard';const views={dashboard,requests,'new-request':newRequest,request:requestDetail,clarify,scope,catalogue,service:()=>service(false),'service-new':()=>service(true),customers,customer:()=>customerPage(false),'customer-new':()=>customerPage(true),quotations,quote:quoteDetail,'quote-edit':quoteEdit,'quote-preview':quotePreview,history,settings,'settings-access':integrations,brand,guide};document.querySelector('#app').innerHTML=page==='sign-in'?signIn():shell(page,(views[page]||dashboard)());document.title=`BuildWise · ${page.split('-').map(s=>s[0].toUpperCase()+s.slice(1)).join(' ')}`;window.scrollTo(0,0)}
let toastTimer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4200)}
function modal(title,body,buttons=''){document.querySelector('#modal-content').innerHTML=`<h2>${title}</h2>${body}<div class="actions">${action('Close','close-modal')}${buttons}</div>`;document.querySelector('#modal').showModal()}
function go(route){location.hash='/'+route}
function syncQuote(r,d){const q={id:d.number,request:r.id,status:d.approved?'Approved':'Draft',total:draftTotal(d),revision:d.revision};const i=state.quotes.findIndex(q=>q.request===r.id);if(i>=0)state.quotes[i]=q;else state.quotes.unshift(q)}
window.addEventListener('hashchange',()=>{document.querySelector('#modal').close();render()});
document.addEventListener('click',e=>{const cat=e.target.closest('[data-category]'),filter=e.target.closest('[data-filter]'),qf=e.target.closest('[data-quote-filter]');if(cat){e.preventDefault();category=cat.dataset.category;render()}if(filter){e.preventDefault();requestFilter=filter.dataset.filter;render()}if(qf){e.preventDefault();quoteFilter=qf.dataset.quoteFilter;render()}const row=e.target.closest('[data-href]');if(row&&!e.target.closest('a,button,input'))go(row.dataset.href);const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
if(a==='menu')document.querySelector('.sidebar').classList.toggle('open');
if(a==='close-modal')document.querySelector('#modal').close();
if(a==='notifications')modal('Your next steps',`<p class="muted">Review unanswered request details and prepare scopes for provider approval.</p><a class="text-link" href="#/requests" data-action="close-modal">Open requests →</a>`);
if(a==='ai')modal('AI assistance is not connected.',`<p class="muted">You can continue by answering catalogue questions and selecting services manually. Your request and answers are retained.</p>`,B('Select services',`scope/${currentRequest().id}`,'box','primary'));
if(a==='confirm-scope'){if(!document.querySelector('#scope-approved').checked){toast('Please confirm that you have reviewed the scope.');return}state.scopeApproved[currentRequest().id]=true;currentRequest().status='Ready to quote';save();toast('Scope review confirmed.');go(`quote-edit/${currentRequest().id}`)}
if(a.startsWith('edit-scope-')){let i=Number(a.split('-').pop()),s=getScope()[i];modal(`Edit ${esc(s.name)}`,`<form id="scope-edit-form">${field('Stage name','name',s.name)}${field('Reviewed scope notes','scopeNotes',s.notes,'textarea')}<input type="hidden" name="index" value="${i}"><button class="btn primary" type="submit">Save notes</button></form>`)}
if(a==='add-scope')modal('Select a catalogue service',`<div style="margin-top:20px">${state.services.filter(s=>s.active).map(s=>`<div class="info-row"><span>${esc(s.name)}</span>${action('Add',`select-service-${s.id}`,'plus','small')}</div>`).join('')}</div>`);
if(a.startsWith('select-service-')){const id=a.slice('select-service-'.length),s=state.services.find(s=>s.id===id);getScope().push({name:s.name,service:s.id,notes:s.description});state.scopeApproved[currentRequest().id]=false;save();document.querySelector('#modal').close();render();toast('Catalogue service added for review.')}
if(a==='print'){const d=getDraft();d.deliveries.push({event:'Print requested',revision:d.revision});save();window.print()}
if(a==='approve'){const d=getDraft();if(!state.scopeApproved[currentRequest().id]){modal('Review the scope first.',`<p class="muted">Confirm your scope review before approving the quotation.</p>`,B('Review scope',`scope/${currentRequest().id}`,'check','primary'));return}modal('Approve this quotation?',`<p class="muted">Confirm that you have checked the scope, quantities, exclusions, conditions and ${money(draftTotal(d))} total for revision ${d.revision}.</p><p style="font-size:12px">Unconfirmed quantities remain subject to the stated assessment conditions.</p>`,action('Confirm approval','confirm-approval','check','primary'))}
if(a==='confirm-approval'){const r=currentRequest(),d=getDraft(r);d.approved=true;d.snapshot={items:structuredClone(getScope(r)),business:structuredClone(state.business),customer:structuredClone(customer(r.customer))};syncQuote(r,d);save();document.querySelector('#modal').close();render();toast('Quotation approved. Print or save the approved revision.')}
if(a==='email'){const d=getDraft();if(!d.approved){toast('Approve the quotation before preparing an email.');return}modal('Review email recipient',`${field('Recipient','recipient',d.recipient||customer(currentRequest().customer).email,'email')}<p class="muted" style="font-size:12px">${quoteNumber(d)} · Revision ${d.revision}<br>Email delivery is not connected. No email will be sent from this screen.</p>`,action('Save recipient','save-recipient','check','primary'))}
if(a==='save-recipient'){const input=document.querySelector('#recipient');if(!input.reportValidity())return;getDraft().recipient=input.value;save();document.querySelector('#modal').close();toast('Recipient saved. Email delivery requires a connected service.')}
if(a.startsWith('view-revision-')){const h=getDraft().history[Number(a.split('-').pop())];modal(`Approved revision ${h.revision}`,`<p>${money(h.rates.reduce((a,b)=>a+b,0))}</p>${h.snapshot.items.map(s=>`<h3>${esc(s.name)}</h3><p class="muted">${esc(s.notes)}</p>`).join('')}<p>${esc(h.exclusions)}</p><p>${esc(h.terms)}</p>`)}
if(a==='forgot')modal('Reset your password',`${field('Account email','reset-email','','email')}<p class="muted" style="font-size:12px">Account recovery will be available when authentication is connected.</p>`)
});
document.addEventListener('submit',e=>{if(!['request-form','clarify-form','customer-form','service-form','quote-form','settings-form','scope-edit-form','signin-form','global-search'].includes(e.target.id))return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));if(!f.checkValidity()){f.reportValidity();return}
if(f.id==='request-form'){let id=Math.max(...state.requests.map(r=>r.id))+1;state.requests.unshift({id,title:d.title,customer:Number(d.customer),category:d.category,status:'Needs clarification',date:'01 Nov 2026',description:d.description,location:d.location,property:d.property});save();go(`request/${id}`);toast('Request saved.')}
if(f.id==='clarify-form'){state.answers[currentRequest().id]=getQuestions(currentRequest()).map((_,i)=>d['answer'+i]||'Unknown');save();toast('Answers saved. Unknown details remain visible.')}
if(f.id==='customer-form'){let id=Number(f.dataset.id)||Math.max(...state.customers.map(c=>c.id))+1,c={id,name:d.name,email:d.email,phone:d.phone,location:d.location};let i=state.customers.findIndex(c=>c.id===id);if(i>=0)state.customers[i]=c;else state.customers.push(c);save();go(`customer/${id}`);toast('Customer saved.')}
if(f.id==='service-form'){let id=f.dataset.id||'SVC-'+String(state.services.length+1).padStart(3,'0');let s={id,name:d.name,category:d.category,description:d.description,unit:d.unit,icon:'tool',questions:d.questions.split('\n').filter(Boolean).length,questionText:d.questions,assessment:d.assessment==='on',active:d.active==='on',inclusions:d.inclusions,exclusions:d.exclusions,stages:d.stages};let i=state.services.findIndex(s=>s.id===id);if(i>=0)state.services[i]=s;else state.services.push(s);save();category='All services';go('catalogue');toast('Service saved.')}
if(f.id==='quote-form'){const r=currentRequest(),q=getDraft(r);if(q.approved){if(!q.snapshot)q.snapshot={items:structuredClone(getScope(r)),business:structuredClone(state.business),customer:structuredClone(customer(r.customer))};const prior=structuredClone(q);delete prior.history;q.history.push(prior);q.revision++}q.approved=false;q.rates=getScope(r).map((_,i)=>Number(d['rate'+i])||0);q.terms=d.terms;q.exclusions=d.exclusions;r.status='Draft quotation';syncQuote(r,q);save();toast('Draft quotation saved.');go(`quote-preview/${r.id}`)}
if(f.id==='settings-form'){state.business={...state.business,...d};save();render();toast('Business details saved.')}
if(f.id==='scope-edit-form'){let s=getScope()[Number(d.index)];s.name=d.name;s.notes=d.scopeNotes;state.scopeApproved[currentRequest().id]=false;save();document.querySelector('#modal').close();render();toast('Scope notes saved.')}
if(f.id==='signin-form')go('dashboard');
if(f.id==='global-search'){go('requests');setTimeout(()=>{const s=document.querySelector('#list-search');if(s){s.value=d.q;s.dispatchEvent(new Event('input',{bubbles:true}))}},0)}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='list-search'){let q=el.value.toLowerCase();document.querySelector('#request-results').innerHTML=requestTable(state.requests.filter(r=>(requestFilter==='All requests'||r.status===requestFilter)&&`${r.title} ${r.id} ${customer(r.customer).name}`.toLowerCase().includes(q)))}if(el.id==='customer-search'){let q=el.value.toLowerCase();document.querySelector('#customer-results').innerHTML=customerRows(state.customers.filter(c=>`${c.name} ${c.email} ${c.location}`.toLowerCase().includes(q)))}if(el.classList.contains('amount')){let sum=[...document.querySelectorAll('.amount')].reduce((a,i)=>a+Number(i.value||0),0);document.querySelector('#quote-total').textContent=money(sum);document.querySelector('#quote-subtotal').textContent=money(sum)}});
if(document.body.dataset.serverShell!=='true')render();
